# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
MP=[['希腊 meta- + pherein → metapherein / metaphora','把东西移到另一边 → 把一种说法移用到另一事物'],['拉丁 metaphora → 法语 métaphore / 英语 metaphor','意义的转移 → 隐喻']]
ME=[['希腊 meta- + aeirein → meteōros','抬起、悬在空中的'],['希腊 meteōron → 拉丁 meteorum → 法语 météore → 英语 meteor','空中现象；现代常特指流星现象']]
MO=[['希腊 meta-“转变” + morphē“形态”','转变形态'],['希腊 metamorphōsis → 拉丁 metamorphosis → 英语 metamorphosis','形态、结构的转变']]
def A(h,a,b):return h+[[a,b]]
WA=[
E('metaphor','英 /ˈmetəfə/；美 /ˈmetəfɔːr/','隐喻；暗喻','把一个领域的画面搬来理解另一个领域：说“时间是金钱”，就是把花钱的画面搬给时间。','meta-“跨过去” + pherein“带、搬”形成希腊 metaphora，经拉丁语、法语传入英语。',MP,'a mountain of work 把堆积如山的画面搬给工作量。metaphor 不一定只出现在诗歌里，日常说“抓住重点”“温暖的欢迎”也在借用具体经验。','a metaphor for；use a metaphor；an extended metaphor。','simile 通常用 like、as 等作明说的比较；metaphor 通常直接借用另一事物来表达。',('The writer uses a journey as a metaphor for life.','作者用旅程来隐喻人生。'),('Calling the office a battlefield is a metaphor.','把办公室叫作战场，是一种隐喻。'),sources=['https://www.etymonline.com/word/metaphor']),
E('metaphoric','英 /ˌmetəˈfɒrɪk/；美 /ˌmetəˈfɔːrɪk/','隐喻的；比喻性的','说到的东西是在借它的特点，不是要按字面认定真的存在。','metaphor + -ic；与 metaphorical 意思接近。',A(MP,'英语 metaphoric','具有隐喻性质的'),'a metaphoric bridge 是沟通、连接的比喻，不一定真有一座桥。metaphoric 与 metaphorical 通常没有必须背下来的严格意义分界，后者更常见于一般表达。','metaphoric meaning；metaphoric language；metaphoric use。','不要为 metaphoric 和 metaphorical 硬编“一个具体、一个抽象”的区别；主要看习惯搭配。',('The wall has a metaphoric meaning in the poem.','诗中的墙具有隐喻意义。'),('The critic explores the image’s metaphoric power.','评论者探讨这个意象的隐喻力量。'),sources=['https://www.etymonline.com/word/metaphoric']),
E('metaphorical','英 /ˌmetəˈfɒrɪkəl/；美 /ˌmetəˈfɔːrɪkəl/','隐喻的；比喻意义上的','给听者一个提示：这里的“桥”“牢笼”“伤口”，可能是在借画面说别的事。','现代可拆 metaphor + -ical，或 metaphoric + -al；文献中 metaphorical 较早，不能把拆法当成确定的先后史。',MP+[['英语 metaphorical / metaphoric 两种形容词','都表示比喻性的；拼写长短不代表出现先后']],'a metaphorical prison 可能是让人觉得无法摆脱的生活处境。使用这个词，往往是在说明字面场景与实际所指之间有一层比喻关系。','a metaphorical meaning；metaphorical language；a metaphorical journey。','literal 是按字面理解；metaphorical 是借另一幅画面表达，未必完全不真实，只是表达方式间接。',('The prison in the final chapter is metaphorical.','最后一章里的牢笼是比喻性的。'),('She described learning a language as a metaphorical journey.','她把学习语言比作一段旅程。'),sources=['https://www.etymonline.com/word/metaphoric']),
E('metaphorically','英 /ˌmetəˈfɒrɪkli/；美 /ˌmetəˈfɔːrɪkli/','用比喻来说；在隐喻意义上','说完一个形象的词，再提醒对方：别真把那幅画面当成事实。','metaphorical + -ly，常读成较紧凑的 -ically。',A(MP,'英语 metaphorical → metaphorically','比喻性的 → 用比喻表达地'),'metaphorically speaking 是常见提示语。I was drowning, metaphorically 是说事情多得应付不过来，不是在水里求救；它澄清说法的层次。','metaphorically speaking；use a word metaphorically。','literally 在严格用法中说按字面；metaphorically 明确说比喻意义，适合避免误解。',('Metaphorically speaking, we are all in the same boat.','打个比方，我们都在同一条船上。'),('She uses the word “home” metaphorically.','她是在比喻意义上使用“家”这个词。')),
E('meteor','英 /ˈmiːtiə/；美 /ˈmiːtiər/','流星；〔旧义〕空中、大气现象','抬头看见夜空划过一道亮光：现代 meteor 通常指这道现象。','希腊 meteōros“悬在空中的”，经拉丁语、法语进入英语；早先指更广的大气现象。',ME,'太空中的小石块、金属碎块等进入大气，产生发光现象，叫 meteor。它不是一颗恒星掉下来。meteorology 仍沿较早的“大气现象”意义，所以是气象学，不是只研究流星。','a bright meteor；a meteor shower；observe a meteor。','meteoroid 是物体；meteor 是穿过大气时的发光现象；meteorite 是落到地表的残留物。',('A bright meteor flashed across the sky.','一颗明亮的流星划过天空。'),('We watched the meteor shower from a dark hillside.','我们在一片黑暗的山坡上观看流星雨。'),sources=['https://www.etymonline.com/word/meteor','https://science.nasa.gov/solar-system/meteors-meteorites/facts/']),
E('meteoroid','/ˈmiːtiərɔɪd/','流星体','先别看天空的亮光，想想产生它的那块太空碎屑本身。','meteor + -oid，现代天文学用来区分物体与它产生的现象。',A(ME,'英语 meteoroid','与流星相关的小型天然天体、碎屑本身'),'meteoroid 可以在太空中运行，尚未形成你看得见的流星。学习时先记物体与现象的区分，比把三种术语都译成“流星”有用。','a small meteoroid；a meteoroid entering the atmosphere。','-oid 常有“类似”的意思，但 meteoroid 在科学中是明确术语，不是“假的流星”。',('The tiny meteoroid travelled through space for years.','这颗微小流星体在太空中运行了多年。'),('A meteoroid can produce a bright meteor when it enters the atmosphere.','流星体进入大气时，可以产生明亮的流星现象。'),sources=['https://www.merriam-webster.com/dictionary/meteoroid','https://www.jpl.nasa.gov/asteroid-watch/fast-facts/']),
E('meteorite','/ˈmiːtiəraɪt/','陨石','亮光已经过去，地面上还留下来自太空的一块物质。','meteor + -ite；-ite 在这里标记相关物体、石质材料。',A(ME,'英语 meteorite','穿过大气后到达地表的天然天体残留物'),'并不是每道流星都能留下可找到的陨石；很多小颗粒在进入大气时就消散。陨石可能含石质或金属，不是外表发黑的普通石头都算。','a meteorite fragment；find a meteorite；a meteorite sample。','meteor 是可见现象，meteorite 是能作为样本研究的残留物；从物体到现象到残留，不是三个完全无关的东西。',('The museum displays a fragment of a meteorite.','博物馆展出了一块陨石碎片。'),('Scientists examined the meteorite’s mineral composition.','科学家检查了这块陨石的矿物组成。'),sources=['https://science.nasa.gov/solar-system/meteors-meteorites/facts/','https://www.etymonline.com/word/meteorite']),
E('meteoric','英 /ˌmiːtiˈɒrɪk/；美 /ˌmiːtiˈɔːrɪk/','流星般迅速耀眼的；与流星有关的；大气来源的〔专门〕','像一道亮光突然抓住所有人的目光，所以可形容迅速成名。','meteor + -ic；保留流星义，也在专门用语里保留早先的大气义。',A(ME,'英语 meteoric','与空中现象有关 → 流星般迅速、耀眼'),'a meteoric rise 是地位或名气飞快上升，虽然流星本身并不是朝上飞才叫流星。这个比喻抓的是快与耀眼，不必自动理解成成功一定短命。地学中的 meteoric water 指降水来源的水。','a meteoric rise；meteoric success；meteoric water。','meteorological 是气象学的；meteoric 日常最常见的是迅速崛起，专业场景仍要看具体所指。',('The singer enjoyed a meteoric rise to fame.','这位歌手迅速走红。'),('The article examines her meteoric career.','这篇文章分析了她迅速崛起的事业历程。'),sources=['https://www.etymonline.com/word/meteoric']),
E('metamorphosis','英 /ˌmetəˈmɔːfəsɪs/；美 /ˌmetəˈmɔːrfəsɪs/','形态变化；蜕变；变态发育','毛毛虫变成蝴蝶，变化大到形态和生活方式都换了一套。','meta-“转变” + morphē“形态”形成希腊 metamorphōsis，经拉丁语借入英语。',MO,'生物学里指发育中的显著形态变化；一般文章也用来写城市、性格或组织的大转变。它强调变化幅度，普通换个发型不一定要用这么重的词。复数是 metamorphoses。','undergo a metamorphosis；a remarkable metamorphosis。','transformation 是更宽的转变；metamorphosis 往往更突出形态或整体面貌明显改变。',('The caterpillar undergoes a remarkable metamorphosis.','毛毛虫经历了一场显著的形态变化。'),('The old factory’s metamorphosis into a library took two years.','旧工厂改造成图书馆，前后花了两年。'),sources=['https://www.etymonline.com/word/metamorphosis']),
E('metamorphose','英 /ˌmetəˈmɔːfəʊz/；美 /ˌmetəˈmɔːrfoʊz/','使变形；发生彻底转变','把 metamorphosis 那场大变化变成一个正在发生的动作。','经法语 métamorphoser，接法语名词 métamorphose、拉丁 metamorphosis；不是一定由英语名词反推出来。',MO[:1]+[['希腊 / 拉丁 metamorphosis → 法语 métamorphose → métamorphoser → 英语 metamorphose','形态变化 → 使改变形态、转变']],'metamorphose into 可以说动物发育，也可以描写一个地方或组织面貌全变。可不及物说事物自己变，也可及物说某种力量使它改变。','metamorphose into；metamorphose something into。','morph 更简短、口语或技术色彩更强；metamorphose 比较正式、形象。',('The abandoned station metamorphosed into a busy arts centre.','废弃车站变成了热闹的艺术中心。'),('The larvae eventually metamorphose into adults.','幼体最终发育变态成为成体。'),sources=['https://www.etymonline.com/word/metamorphose']),
E('metamorphosed','英 /ˌmetəˈmɔːfəʊzd/；美 /ˌmetəˈmɔːrfoʊzd/','已经变形的；已转变的；经过变质作用的','原来的样子已经被改造，眼前看到的是变化后的结果。','metamorphose + -d。',MO[:1]+[['法语 métamorphoser → 英语 metamorphose → metamorphosed','使改变形态 → 已经发生变化的']],'has metamorphosed into 说某物已经变成另一面貌；metamorphosed rock 在地质学中说岩石经过了变质作用。不要把所有过去分词都按“被某人改造”理解，变化也可自然发生。','metamorphosed rock；have metamorphosed into。','metamorphic 是类型或性质描述；metamorphosed 更突出经历过变化这一过程。',('The neighbourhood has metamorphosed into a lively cultural district.','这个街区已经转变成活跃的文化区。'),('The sample contains heavily metamorphosed rock.','这个样本含有经历强烈变质作用的岩石。'),sources=['https://www.etymonline.com/word/metamorphose','https://www.usgs.gov/faqs/what-are-metamorphic-rocks']),
E('metamorphic','英 /ˌmetəˈmɔːfɪk/；美 /ˌmetəˈmɔːrfɪk/','变质的〔地质〕；形态改变的','原来的岩石仍是固体，却在温度、压力、流体等作用下换了内部结构或矿物组合。','meta-“转变” + morph-“形态” + -ic；英语与 metamorphosis 词族相联，地质义在十九世纪确立。',MO[:1]+[['英语 metamorphic','形态改变的 → 地质学中的变质的']],'marble 是由石灰岩等原岩经历变质作用形成的岩石。变质岩不是岩石完全熔化后再凝固；后一过程属于火成岩形成的范围，不能只用“受热”把两者合并。','metamorphic rock；metamorphic minerals；metamorphic conditions。','metamorphic 不是 metaphorical：前者改形态，后者搬用意义，morph 与 phor 是不同部分。',('Marble is a metamorphic rock.','大理岩是一种变质岩。'),('The minerals reveal the rock’s metamorphic history.','这些矿物揭示了岩石经历过的变质过程。'),sources=['https://www.etymonline.com/word/metamorphic','https://www.usgs.gov/faqs/what-are-metamorphic-rocks']),
E('metamorphism','英 /ˌmetəˈmɔːfɪzəm/；美 /ˌmetəˈmɔːrfɪzəm/','变质作用〔地质〕；形态转变','关注的是岩石被重新“改造”的过程，而不是最后那块石头的名称。','metamorph- + -ism；常接 metamorphic 词族，也与法语 métamorphisme 对应。',MO[:1]+[['英语 metamorphic / 法语 métamorphisme → 英语 metamorphism','变质的 → 改变矿物和结构的变质作用']],'岩石经历 metamorphism 时，矿物可能重新结晶、形成新的排列。核心是固态条件下的改变，不能把熔成岩浆再冷却也都算成同一过程。','regional metamorphism；contact metamorphism；undergo metamorphism。','metamorphosis 常说动物或整体面貌的蜕变；metamorphism 在现代学习中优先记地质过程。',('Heat from the intrusion caused contact metamorphism.','侵入岩体的热量引发了接触变质作用。'),('Metamorphism changed both the minerals and the texture of the rock.','变质作用改变了岩石的矿物组成和结构。'),sources=['https://www.etymonline.com/word/metamorphism','https://www.usgs.gov/faqs/what-are-metamorphic-rocks']),
]
